  ('kaunnst-ma-an-hundada-zreissn', 'Kaunnst ma an Hundada zreissn?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kannst du mir einen Hunderter zerreißen?', '[{"kategorie": "", "text": "Kannst du mir einen Hunderter in kleinere Scheine wechseln?  2. Kannst du mir einen Hunderter in kleinere Stückelung \"zerlegen\"?"}]'::jsonb, ''),
  ('si-zareissn', 'si zareissn', '', '', '', 'Grundwortschatz Wienerisch', 'sich zerreißen', '[{"kategorie": "wörtlich", "text": "\"sich in Stücke reißen\" (vom althochdeutschen \"rízan\"=\"in Stücke reißen\")"}, {"kategorie": "fig.", "text": "sich aufreiben, sich aufopfern, [[sich]] zersprageln"}, {"kategorie": "", "text": "sich kringeln vor Lachen, [[sich]] einen Ast lachen, [[sich]] zerbären, [[sich]] zerfetzen"}]'::jsonb, 'I kaunn mi ned zareissn!'),
  ('i-zreiss-mi-fia-di-und-du-riasd-ned-amoi-in-klaan-finga', 'I zreiss mi fia di, und du riasd ned amoi in klaan Finga!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich zerreiße mich für dich, und du rührst nicht einmal den kleinen Finger!', '[{"kategorie": "wörtlich", "text": "\"Ich opfere mich für dich auf,  rührst nicht einmal den kleinen Finger!\"  2. Ich reiße mir den Hintern auf, und du tust gar nichts!  3. Ich zerfranse mich für dich, und du bewegst keinen Finger!"}]'::jsonb, 'si zareissn'),
  ('i-daschbraagl-mi-fia-di-und-du-riasd-ned-amoi-in-klaan-finga', 'I daschbraagl mi fia di, und du riasd ned amoi in klaan Finga!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich derspragle mich für dich, und du rührst nicht einmal den kleinen Finger!', '[{"kategorie": "wörtlich", "text": "\"Ich opfere mich für dich auf,  rührst nicht einmal den kleinen Finger!\"  2. Ich reiße mir den Hintern auf, und du tust gar nichts!  3. Ich zerfranse mich für dich, und du bewegst keinen Finger!"}]'::jsonb, 'si daschbraagln'),
