  ('ruck-a-weng-zuwa-zu-mia', 'Ruck a weng zuwa zu mia!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Rück ein wenig zuwa zu mir!', '[{"kategorie": "wörtlich", "text": "\"Rück ein wenig näher zu mir ran!\"  2. Rück ein bisschen näher!  3. Na los, rutsch ein Stück näher ran!"}]'::jsonb, ''),
  ('dea-kraeud-ia-zuwe-wiara-ue40-romeo-mit-toaschlusspanik', 'Dea kräud ia zuwe wiara Ü40-Romeo mit Toaschlusspanik!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der kräult ihr zuwe wie ein Ü40-Romeo mit Torschlusspanik!', '[{"kategorie": "wörtlich", "text": "\"Der kriecht an sie ran wie ein Ü40-Romeo mit Torschlusspanik!\"  2. Der macht sich an sie ran wie ein Spätzünder mit Torschlusspanik!  3. Der hängt sich an sie ran wie ein Ertrinkender an die letzte Rettungsboje!"}]'::jsonb, ''),
  ('dea-hod-a-joa-bei-ia-braadld-bis-eam-zuwalossn-hod', 'Dea hod a Joa bei ia braadld, bis eam zuwalossn hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er hat ein Jahr bei ihr gebraten, bis sie ihn zuwagelassen hat!', '[{"kategorie": "wörtlich", "text": "\"Er hat ein Jahr bei ihr gebraten, bis sie ihn rangelassen hat!\"  2. Er hat ein Jahr lang gebaggert, bis sie ihn endlich an sich rangelassen hat!  3. Der hat ein jahr lang brav Männchen gemacht, bis er an sie ran durfte!"}]'::jsonb, ''),
